# Standalone reader for pack-0edbe: resolves every entry (using reconstructed content for zeroed entries), verifies SHA-1.
import json, hashlib, zlib, os, sys
REPO="/app/repo.git"; os.chdir(REPO)
results={k:(t,bytes.fromhex(b)) for k,[t,b] in json.load(open("/tmp/work/results.json")).items()}
pack=open("objects/pack/pack-0edbe236157d7f40502eaa2e054bc68160f770ab.pack","rb").read()
entries=[]
for line in open("/tmp/pack0edbe-index.txt"):
    parts=line.split()
    if len(parts)>=2 and parts[0].isdigit(): entries.append((int(parts[0]),parts[1]))
entries.sort(); offs=[e[0] for e in entries]+[len(pack)-20]
by_off={o:i for i,(o,_) in enumerate(entries)}
TYPES={1:"commit",2:"tree",3:"blob",4:"tag"}
def parse_hdr(off):
    c=pack[off]; t=(c>>4)&7; size=c&15; shift=4; p=off+1
    while c&0x80:
        c=pack[p]; p+=1; size|=(c&0x7f)<<shift; shift+=7
    base=None
    if t==6:
        c=pack[p]; p+=1; x=c&0x7f
        while c&0x80:
            c=pack[p]; p+=1; x=((x+1)<<7)|(c&0x7f)
        base=off-x
    elif t==7: base=pack[p:p+20].hex(); p+=20
    return t,size,base,p
def varint(d,i):
    v=0;s=0
    while True:
        b=d[i]; i+=1; v|=(b&0x7f)<<s; s+=7
        if not b&0x80: return v,i
def apply_delta(base,delta):
    i=0; src,i=varint(delta,i); tgt,i=varint(delta,i); assert src==len(base)
    out=bytearray()
    while i<len(delta):
        c=delta[i]; i+=1
        if c&0x80:
            off=0;sz=0
            if c&0x01: off|=delta[i]; i+=1
            if c&0x02: off|=delta[i]<<8; i+=1
            if c&0x04: off|=delta[i]<<16; i+=1
            if c&0x08: off|=delta[i]<<24; i+=1
            if c&0x10: sz|=delta[i]; i+=1
            if c&0x20: sz|=delta[i]<<8; i+=1
            if c&0x40: sz|=delta[i]<<16; i+=1
            if sz==0: sz=0x10000
            out+=base[off:off+sz]
        elif c: out+=delta[i:i+c]; i+=c
        else: raise ValueError("bad delta op")
    assert len(out)==tgt
    return bytes(out)
cache={}
def inflate(p,end):
    d=zlib.decompressobj(); out=d.decompress(pack[p:end])
    if not d.eof: raise ValueError("stream not finished")
    return out
def resolve(idx):
    off,oid=entries[idx]
    if oid in cache: return cache[oid]
    t,size,base,p=parse_hdr(off); end=offs[idx+1]
    try:
        data=inflate(p,end); assert len(data)==size
    except Exception as e:
        if oid in results:
            cache[oid]=results[oid]; return cache[oid]
        raise RuntimeError(f"{oid} corrupt and not reconstructed: {e}")
    if t in TYPES:
        res=(TYPES[t],data)
    else:
        if t==6: btyp,bdata=resolve(by_off[base])
        else:
            bidx=[i for i,(o,x) in enumerate(entries) if x==base]
            if bidx: btyp,bdata=resolve(bidx[0])
            else: btyp,bdata=results[base]
        res=(btyp,apply_delta(bdata,data))
    cache[oid]=res; return res
ok=0; bad=[]
out={}
for i,(off,oid) in enumerate(entries):
    try:
        typ,body=resolve(i)
    except Exception as e:
        bad.append((oid,str(e))); continue
    if hashlib.sha1(b"%s %d\x00"%(typ.encode(),len(body))+body).hexdigest()==oid:
        ok+=1; out[oid]=(typ,body)
    else: bad.append((oid,"sha mismatch"))
